<?php
$sourceProducts=[];$sourceLots=[];
foreach($rawAvailable as$r){
 if(($r['item_status']??'')!=='active'||($r['item_kind']??'')!=='raw_material'||($r['item_unit']??'')!=='kg'||$r['item_deleted']!==null||$r['production_date']>date('Y-m-d'))continue;
 $id=(int)$r['item_id'];$counted=!empty($r['track_pieces']);
 // Carcasses counted in pieces leave by pieces: lots without free pieces are skipped.
 if($counted&&(int)$r['quantity_pieces']<=(int)$r['reserved_pieces'])continue;
 $sourceLots[]=$r;
 if(!isset($sourceProducts[$id]))$sourceProducts[$id]=['name'=>$r['item_name'],'quantity'=>0,'pieces'=>0,'counted'=>$counted];
 $sourceProducts[$id]['quantity']=round($sourceProducts[$id]['quantity']+(float)$r['quantity_kg']-(float)$r['reserved_kg'],3);
 if($counted)$sourceProducts[$id]['pieces']+=(int)$r['quantity_pieces']-(int)$r['reserved_pieces'];
}
// Products offered per source material: the butchery products referential (046), or every product before it.
$offered=array_map(static fn($i)=>['id'=>(int)$i['id'],'name'=>$i['name'],'pieces'=>!empty($i['track_pieces']),'shelf'=>$i['default_shelf_life_days']!==null?(int)$i['default_shelf_life_days']:null,'sources'=>$productSources===null?null:array_keys(array_filter($productSources,static fn($products)=>in_array((string)$i['id'],array_map('strval',$products),true)))],$items);
?>
<div class="transformation-form" data-transformation-form data-products="<?=e(json_encode($offered,JSON_UNESCAPED_UNICODE))?>"<?=$productSources!==null?' data-products-filtered':''?>>
<fieldset class="receipt-control-step"><legend><span aria-hidden="true">1</span> Que sortez-vous de la chambre froide ?</legend>
<div class="form-grid"><label class="form-wide"><span>Produit source *</span><select name="source_item_id" required><option value="">Choisir le produit à transformer</option><?php foreach($sourceProducts as$id=>$product):?><option value="<?=e($id)?>" data-pieces="<?=$product['counted']?'1':'0'?>" data-name="<?=e($product['name'])?>"><?=e($product['name'].' · '.($product['counted']?number_format($product['pieces'],0,',',' ').' pièce(s), ':'').$kg($product['quantity']).' kg disponibles')?></option><?php endforeach;?></select></label><label data-transform-pieces hidden><span>Pièces sorties *</span><input type="number" name="quantity_pieces" min="1" step="1" inputmode="numeric" disabled></label><label><span data-transform-kg-label>Quantité sortie (kg) *</span><input type="number" name="quantity_kg" min="0.001" step="0.001" required></label><label><span>Date de transformation *</span><input type="date" name="production_date" value="<?=date('Y-m-d')?>" max="<?=date('Y-m-d')?>" required></label></div>
<p class="livestock-guide" data-transform-available aria-live="polite">Choisissez le produit. Les lots seront proposés automatiquement, par DLC la plus proche.</p>
<?php if(!$sourceProducts):?><p class="app-alert" role="status">Aucune matière disponible. Réceptionnez des carcasses avant d’enregistrer une transformation.</p><?php endif;?>
<details class="transform-lots"><summary>Voir ou modifier les lots utilisés</summary><p>La proposition dépend du stock actuel. Les lots et quantités sont confirmés lors de l’enregistrement.</p><label><span>Choix des lots</span><select name="lot_mode"><option value="auto">Automatique · DLC la plus proche en premier</option><option value="manual">Choisir les lots autorisés pour ce prélèvement</option></select></label>
<div class="transform-lot-choices"><?php foreach($sourceLots as$r):?><label class="transform-lot-choice" data-transform-lot data-item="<?=e($r['item_id'])?>" data-quantity="<?=e(round((float)$r['quantity_kg']-(float)$r['reserved_kg'],3))?>" data-pieces="<?=!empty($r['track_pieces'])?(int)$r['quantity_pieces']-(int)$r['reserved_pieces']:''?>" data-expiry="<?=e($r['expiry_date'])?>" data-production="<?=e($r['production_date'])?>"><input type="checkbox" name="source_lot_ids[]" value="<?=e($r['id'])?>" checked><span><strong><?=e($r['lot_number'])?></strong><small><?=!empty($r['track_pieces'])?e(number_format((int)$r['quantity_pieces']-(int)$r['reserved_pieces'],0,',',' ')).' pièce(s), ':''?><?=$kg((float)$r['quantity_kg']-(float)$r['reserved_kg'])?> kg disponibles · DLC <?=e(date('d/m/Y',strtotime($r['expiry_date'])))?></small><small data-transform-take></small></span></label><?php endforeach;?></div><p class="receipt-control-help">En mode manuel, seuls les lots cochés sont utilisés, toujours par DLC la plus proche. Leur origine reste enregistrée dans le dossier.</p></details>
</fieldset>
