<?php if($productSources!==null):?><p class="transform-products-hint" data-transform-products-hint aria-live="polite"><span data-transform-products-text>Choisissez d’abord le produit source : seuls ses produits seront proposés.</span> <a href="<?=e(base_url('butchery/products'))?>"><i class="bi bi-tags" aria-hidden="true"></i> Produits par matière</a></p><?php endif;?>
